import type { Response, RequestInit } from "undici";

const CAUSES: Record<number, string[]> = {
    400: ["No body was provided"],
    401: [
        "The XSRF- or client-token is missing/invalid (make sure the controller is bootstrapped)"
    ],
    403: ["An identifier does not exist/is private"],
    404: ["The provided URL does not exist"],
    412: ["The changeToken is missing/invalid"],
    500: [
        "The content-type header is missing/invalid",
        "Client is fully authorized to view children (e.g. a specific policy), but no child exists for the given identifier"
    ],
    503: ["Axon is temporarily unavailable. Please retry in a moment."]
};

const MAX_BODY = 500;

export default class RequestError extends Error {
    override readonly name = "RequestError";
    readonly status: number;
    readonly url: string;
    readonly res: Response;
    readonly body: string;

    private constructor(init: RequestInit, res: Response, body: string) {
        super(buildMessage(init, res, body));
        this.status = res.status;
        this.url = res.url;
        this.res = res;
        this.body = body;
    }

    static async from(init: RequestInit, res: Response) {
        const body = await res.text().catch(() => "");
        return new RequestError(init, res, body.slice(0, MAX_BODY));
    }
}

function buildMessage(init: RequestInit, res: Response, body: string) {
    const status = res.statusText ? `${res.status} ${res.statusText}` : `${res.status}`;
    const causes = CAUSES[res.status] ?? [];
    if (res.url.includes("undefined") || res.url.includes("null"))
        causes.unshift("APPLICABLE: url contains undefined");

    return [
        `${init.method ?? "GET"}-request failed with status code ${status}`,
        causes.length === 0 && "No likely cause found",
        causes.length === 1 && `Likely cause: ${causes[0]}`,
        causes.length > 1 && `Likely causes:${causes.map(c => `\n- ${c}`)}`,
        body,
    ].filter(Boolean).join("\n");
}